//! The canonical cola layout: one way to write a model, so that files
//! regenerated by tools are byte-deterministic and formatting is
//! idempotent.
//!
//! - four spaces of indentation per level;
//! - an entity with no children whose one-line form fits in
//!   [`WIDTH`] columns is written on one line, otherwise one field per
//!   line, every field line ending in `,` (the last included, so an
//!   append never touches the line before it), and the closing `;` on
//!   its own line;
//! - fields before child entities, in source order;
//! - a list fits on its field's line or has one element per line,
//!   each ending in `,`, with `]` at the field's indentation;
//! - a string with a newline is a `"""` block when that reads back
//!   exactly, otherwise a quoted one-liner; see [`literal`];
//! - leading comments stand on their own lines at their item's
//!   indentation, a trailing comment follows the item on its line after
//!   one space; an entity whose header, fields or close carry a comment
//!   is never written on one line, though a comment after its `;` is.

use crate::model::config_model::{Comments, ConfigModel, ConfigValue, NodeId};
use crate::model::literal;

pub use crate::model::literal::quote;

/// Line width beyond which an entity is written one field per line.
pub const WIDTH: usize = 80;
const INDENT: &str = "    ";

/// A value as one-line cola text.
pub fn value_text(value: &ConfigValue) -> String {
    match value {
        ConfigValue::Number(n) => n.text().to_string(),
        ConfigValue::Boolean(b) => b.to_string(),
        ConfigValue::String(s) => quote(s),
        ConfigValue::Symbol(s) => s.clone(),
        ConfigValue::Reference(path) => format!("@{path}"),
        ConfigValue::List(items) => {
            let items: Vec<String> = items.iter().map(value_text).collect();
            format!("[{}]", items.join(", "))
        }
    }
}

fn fits(line: &str) -> bool {
    line.chars().count() <= WIDTH
}

fn trailing(comments: &Comments) -> String {
    comments
        .trailing
        .as_ref()
        .map(|c| format!(" //{c}"))
        .unwrap_or_default()
}

fn leading_lines(comments: &Comments, indent: &str, out: &mut String) {
    for c in &comments.leading {
        out.push_str(&format!("{indent}//{c}\n"));
    }
}

/// A field on its own line at `depth`, with its trailing comma, between
/// its comments.
fn field_lines(
    name: &str,
    value: &ConfigValue,
    comments: &Comments,
    depth: usize,
    out: &mut String,
) {
    let indent = INDENT.repeat(depth);
    leading_lines(comments, &indent, out);
    let one_line = format!("{indent}{name}: {},", value_text(value));
    match value {
        ConfigValue::List(items) if !items.is_empty() && !fits(&one_line) => {
            out.push_str(&format!("{indent}{name}: [\n"));
            let inner = INDENT.repeat(depth + 1);
            for item in items {
                out.push_str(&format!("{inner}{},\n", value_text(item)));
            }
            out.push_str(&format!("{indent}],"));
        }
        ConfigValue::String(s) if s.contains('\n') => match literal::block(s, &indent, INDENT) {
            Some(block) => out.push_str(&format!("{indent}{name}: {block},")),
            None => out.push_str(&one_line),
        },
        _ => out.push_str(&one_line),
    }
    out.push_str(&trailing(comments));
    out.push('\n');
}

fn write_entity(model: &ConfigModel, id: NodeId, depth: usize, out: &mut String) {
    let Some(node) = model.get_node(id) else {
        return;
    };
    let entity = node.borrow();
    let indent = INDENT.repeat(depth);
    leading_lines(&entity.comments, &indent, out);
    let header = format!("{}:", entity.declaration());
    let after_close = trailing(&entity.closing);

    let commented = entity.comments.trailing.is_some()
        || !entity.closing.leading.is_empty()
        || entity.fields.iter().any(|f| !f.comments.is_empty());
    if entity.children.is_empty() && !commented {
        let fields: Vec<String> = entity
            .fields
            .iter()
            .map(|f| format!("{}: {}", f.name, value_text(&f.value)))
            .collect();
        let one_line = if fields.is_empty() {
            format!("{indent}{header};")
        } else {
            format!("{indent}{header} {};", fields.join(", "))
        };
        if fits(&one_line) && !entity.fields.iter().any(|f| has_newline(&f.value)) {
            out.push_str(&one_line);
            out.push_str(&after_close);
            out.push('\n');
            return;
        }
    }

    out.push_str(&indent);
    out.push_str(&header);
    out.push_str(&trailing(&entity.comments));
    out.push('\n');
    for field in &entity.fields {
        field_lines(&field.name, &field.value, &field.comments, depth + 1, out);
    }
    for &child in &entity.children {
        write_entity(model, child, depth + 1, out);
    }
    leading_lines(&entity.closing, &INDENT.repeat(depth + 1), out);
    out.push_str(&indent);
    out.push(';');
    out.push_str(&after_close);
    out.push('\n');
}

/// Whether the one-line form of the value would hold a newline, which
/// only a string can.
fn has_newline(value: &ConfigValue) -> bool {
    matches!(value, ConfigValue::String(s) if s.contains('\n'))
}

impl ConfigModel {
    /// The model in canonical cola, as one block body: every root
    /// entity in order, then the comments at the end of the block, no
    /// fences. Empty for an empty model.
    pub fn to_cola(&self) -> String {
        let mut out = String::new();
        if let Some(root) = self.get_node(self.root_id()) {
            let root = root.borrow();
            for &child in &root.children {
                write_entity(self, child, 0, &mut out);
            }
            leading_lines(&root.closing, "", &mut out);
        }
        out
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn model_with(fields: &[(&str, ConfigValue)]) -> ConfigModel {
        let mut model = ConfigModel::new();
        let root = model.root_id();
        let a = model.add_entity(root, "a", None, None).unwrap();
        for (name, value) in fields {
            model.add_field_to_entity(a, name, value.clone()).unwrap();
        }
        model
    }

    #[test]
    fn values_as_text() {
        use ConfigValue::*;
        assert_eq!(value_text(&Symbol("parsed".into())), "parsed");
        assert_eq!(value_text(&Reference("claims/cl-1".into())), "@claims/cl-1");
        assert_eq!(value_text(&List(vec![])), "[]");
        assert_eq!(
            value_text(&List(vec![
                Symbol("a".into()),
                String("b c".into()),
                Number(3.into())
            ])),
            "[a, \"b c\", 3]"
        );
    }

    #[test]
    fn short_entities_fit_on_one_line_and_long_ones_do_not() {
        let mut model = ConfigModel::new();
        let root = model.root_id();
        let a = model.add_entity(root, "a", None, None).unwrap();
        model
            .add_field_to_entity(a, "x", ConfigValue::Number(1.into()))
            .unwrap();
        model
            .add_field_to_entity(a, "y", ConfigValue::Number(2.0.into()))
            .unwrap();
        let b = model.add_entity(root, "b", Some("bs"), None).unwrap();
        let k = model.add_entity(b, "k", None, None).unwrap();
        model
            .add_field_to_entity(k, "long", ConfigValue::String("x".repeat(70)))
            .unwrap();
        model.add_entity(root, "empty", None, None).unwrap();
        let expected = format!(
            "a: x: 1, y: 2.0;\nb plural bs:\n    k:\n        long: \"{}\",\n    ;\n;\nempty:;\n",
            "x".repeat(70)
        );
        assert_eq!(model.to_cola(), expected);
    }

    #[test]
    fn long_lists_break_one_element_per_line() {
        let items: Vec<ConfigValue> = (0..12)
            .map(|i| ConfigValue::Symbol(format!("element-{i}")))
            .collect();
        let model = model_with(&[("tags", ConfigValue::List(items))]);
        let text = model.to_cola();
        assert!(
            text.starts_with("a:\n    tags: [\n        element-0,\n"),
            "{text}"
        );
        assert!(text.ends_with("        element-11,\n    ],\n;\n"), "{text}");
    }

    #[test]
    fn comments_take_their_places_and_forbid_the_one_line_form() {
        let mut model = ConfigModel::new();
        let root = model.root_id();
        let a = model.add_entity(root, "a", None, None).unwrap();
        model
            .add_field_to_entity(a, "x", ConfigValue::Number(1.into()))
            .unwrap();
        model
            .add_field_to_entity(a, "y", ConfigValue::Number(2.into()))
            .unwrap();
        {
            let node = model.get_node(a).unwrap();
            let mut node = node.borrow_mut();
            node.comments.leading.push(" about a".into());
            node.comments.trailing = Some(" header".into());
            node.fields[0].comments.trailing = Some(" one".into());
            node.fields[1].comments.leading.push(" two".into());
            node.closing.leading.push(" done".into());
            node.closing.trailing = Some(" closed".into());
        }
        let b = model.add_entity(root, "b", None, None).unwrap();
        model
            .add_field_to_entity(b, "x", ConfigValue::Number(1.into()))
            .unwrap();
        model.get_node(b).unwrap().borrow_mut().closing.trailing = Some(" short".into());
        model
            .get_node(root)
            .unwrap()
            .borrow_mut()
            .closing
            .leading
            .push(" end of block".into());
        assert_eq!(
            model.to_cola(),
            "// about a\na: // header\n    x: 1, // one\n    // two\n    y: 2,\n    // done\n; // closed\nb: x: 1; // short\n// end of block\n"
        );
    }

    #[test]
    fn multi_line_strings_become_blocks() {
        let model = model_with(&[
            ("gloss", ConfigValue::String("one\ntwo".into())),
            ("n", ConfigValue::Number(1.into())),
        ]);
        assert_eq!(
            model.to_cola(),
            "a:\n    gloss: \"\"\"\n        one\n        two\n    \"\"\",\n    n: 1,\n;\n"
        );
        // A string the block form cannot reproduce stays quoted.
        let model = model_with(&[("odd", ConfigValue::String("has \"\"\" in\nit".into()))]);
        assert_eq!(model.to_cola(), "a:\n    odd: 'has \"\"\" in\\nit',\n;\n");
    }
}
